public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                visit(grid, i, j, 0); // Mark the oil as visited
            }
        }
    }

    return count;
}

private static void visit(char[][] grid, int row, int col, int depth) {
    if (row < 0 || col < 0 || row >= grid.length || col >= grid[row].length || grid[row][col] != '@' || depth > 1) {
        return;
    }

    grid[row][col] = ' '; // Mark the oil as visited
    visit(grid, row + 1, col, depth + 1); // Check down
    visit(grid, row - 1, col, depth + 1); // Check up
    visit(grid, row, col + 1, depth + 1); // Check right
    visit(grid, row, col - 1, depth + 1); // Check left
}

