public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    if (low == high) return steppingNumbers; // Early return for single number case

    for (int num = 0; num <= 9; num++) {
        backtrack(num, low, high, steppingNumbers);
    }
    steppingNumbers.sort(Integer::compareTo);
    return steppingNumbers;
}

private static void backtrack(int num, int low, int high, List<Integer> steppingNumbers) {
    if (num < low) return;

    if (num > high) {
        steppingNumbers.add(num);
        return;
    }

    for (int digit = -1; digit <= 1; digit++) {
        if (digit == 0) continue; // Skip zero to avoid leading zeros
        int nextNum = num * 10 + digit;
        backtrack(nextNum, low, high, steppingNumbers);
    }
}

