                dpHorizontal[i][j] = (j > 0) ? dpHorizontal[i][j - 1] + 1 : 1;
                dpVertical[i][j] = (i > 0) ? dpVertical[i - 1][j] + 1 : 1;
                int diagonal = (i > 0 && j > 0) ? dpDiagonal[i - 1][j - 1] + 1 : 1;
                int antiDiagonal = (i < rows - 1 && j < cols - 1) ? dpAntiDiagonal[i + 1][j + 1] + 1 : 1;
                dpDiagonal[i][j] = diagonal;
                dpAntiDiagonal[i][j] = antiDiagonal;
